import{_ as i,c as a,o as e,b0 as n}from"./chunks/framework.BWMBvyU7.js";const p="/programming-docs/assets/105232B10-0-1777982713978-45.B_ZAajRr.jpg",l="/programming-docs/assets/10523260c-1-1777982764871-47.Qvg_UiCf.jpg",u=JSON.parse('{"title":"LV600-栈上的函数","description":null,"frontmatter":{"title":"LV600-栈上的函数","date":"2026-05-05T20:04:30.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/memory/126d4437272e13d97f747c61","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-05-05T20:04:30.317Z","fulluuid":"97f747c61cf14124a1712ac110ab2d53","useduuid":"97f747c61"}},"headers":[],"relativePath":"sdoc/Language/c/memory/126d4437272e13d97f747c61.md","filePath":"sdoc/01-编程语言/01-C语言/30-内存管理/LV600-栈上的函数.md","lastUpdated":1777987950000}'),t={name:"sdoc/Language/c/memory/126d4437272e13d97f747c61.md"};function h(d,s,r,k,c,o){return e(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="lv600-栈上的函数" tabindex="-1">LV600-栈上的函数 <a class="header-anchor" href="#lv600-栈上的函数" aria-label="Permalink to &quot;LV600-栈上的函数&quot;">​</a></h1><p>函数的调用和栈是分不开的，没有栈就没有函数调用，本节就来讲解函数在栈上是如何被调用的。</p><h2 id="一、-栈帧-活动记录" tabindex="-1">一、 栈帧/活动记录 <a class="header-anchor" href="#一、-栈帧-活动记录" aria-label="Permalink to &quot;一、 栈帧/活动记录&quot;">​</a></h2><p>当发生函数调用时，会将函数运行需要的信息全部压入栈中，这常常被称为<strong>栈帧</strong>（Stack Frame）或活动记录（Activate Record）。活动记录一般包括以下几个方面的内容：</p><p>（1）函数的返回地址，也就是函数执行完成后从哪里开始继续执行后面的代码。例如：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a, b, c;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>站在 C 语言的角度看，<code>func()</code> 函数执行完成后，会继续执行 <code>c=a+b;</code> 语句，那么返回地址就是该语句在内存中的位置。</p><blockquote><p>注意：C 语言代码最终会被编译为机器指令，确切地说，返回地址应该是下一条指令的地址，这里之所以说是下一条 C 语言语句的地址，仅仅是为了更加直观地说明问题。</p></blockquote><p>（2）参数和局部变量。有些编译器，或者编译器在开启优化选项的情况下，会通过寄存器来传递参数，而不是将参数压入栈中，我们暂时不考虑这种情况。</p><p>（3）编译器自动生成的临时数据。例如，当函数返回值的长度较大（比如占用 40 个字节）时，会先将返回值压入栈中，然后再交给函数调用者。</p><blockquote><p>当返回值的长度较小（char、int、long 等）时，不会被压入栈中，而是先将返回值放入寄存器，再传递给函数调用者。</p></blockquote><p>（4）一些需要保存的寄存器，例如 ebp、ebx、esi、edi 等。之所以要保存寄存器的值，是为了在函数退出时能够恢复到函数调用之前的场景，继续执行上层函数。</p><p>下图是一个函数调用的实例：</p><p><img src="`+p+`" alt="函数调用实例"></p><p>上图是在 Windows 下使用 VS2010 Debug 模式编译时一个函数所使用的栈内存，可以发现，理论上 ebp 寄存器应该指向栈底，但在实际应用中，它却指向了 old ebp。</p><blockquote><p>在寄存器名字前面添加&quot;old&quot;，表示函数调用之前该寄存器的值。</p></blockquote><p>当发生函数调用时：</p><ul><li>实参、返回地址、ebp 寄存器首先入栈；</li><li>然后再分配一块内存供局部变量、返回值等使用，这块内存一般比较大，足以容纳所有数据，并且会有冗余；</li><li>最后将其他寄存器的值压入栈中。</li></ul><p>需要注意的是，不同编译器在不同编译模式下所产生的函数栈并不完全相同，例如在 VS2010 下选择 Release 模式，编译器会进行大量优化，函数栈的样貌荡然无存，就无法看出效果了，所以这里是以 VS2010 Debug 模式为例进行分析。</p><h2 id="二、-关于数据的定位" tabindex="-1">二、 关于数据的定位 <a class="header-anchor" href="#二、-关于数据的定位" aria-label="Permalink to &quot;二、 关于数据的定位&quot;">​</a></h2><p>由于 esp 的值会随着数据的入栈而不断变化，要想根据 esp 找到参数、局部变量等数据是比较困难的，所以在实现上是根据 ebp 来定位栈内数据的。ebp 的值是固定的，数据相对 ebp 的偏移也是固定的，ebp 的值加上偏移量就是数据的地址。</p><p>例如一个函数的定义如下：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 28.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    //TODO:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>调用形式为：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">92</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>那么函数的活动记录如下图所示：</p><p><img src="`+l+'" alt="函数活动记录"></p><p>这里我们假设两个局部变量挨着，并且第一个变量和 old ebp 也挨着（实际上它们之间有 4 个字节的空白），如此，第一个参数的地址是 <code>ebp+12</code>，第二个参数的地址是 <code>ebp+8</code>，第一个局部变量的地址是 <code>ebp-4</code>，第二个局部变量的地址是 <code>ebp-8</code>。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',30)])])}const E=i(t,[["render",h]]);export{u as __pageData,E as default};
